def merge_sort(items):
    if len(items) <= 1:
        return list(items)
    mid = len(items) // 2
    return merge_sorted(merge_sort(items[:mid]), merge_sort(items[mid:]))

def top_three(results):
    ranked = sorted(results, key=lambda r: (-r[1], r[0]))
    return [name for name, _ in ranked[:3]]
